window.AUTH=window.AUTH||{};window.AUTH["17-1229"]={"d":"17-1229","id":"2018/17-1229","n":"Helsinn Healthcare S.A. v. Teva Pharmaceuticals USA Inc.","briefs":[{"k":"petitioner","label":"Brief of petitioner Helsinn Healthcare S.A.","date":"2018-08-23","url":"https://www.supremecourt.gov/DocketPDF/17/17-1229/60444/20180823120304973_17-1229ts.pdf","side":"pet","n":54},{"k":"united-states","label":"Brief amicus curiae of United States of America","date":"2018-08-30","url":"https://www.supremecourt.gov/DocketPDF/17/17-1229/62207/20180830112539978_17-1229tsacUnitedStates.pdf","side":"us","n":33},{"k":"respondent","label":"Brief of respondents Teva Pharmaceuticals USA, Inc., et al.","date":"2018-10-09","url":"https://www.supremecourt.gov/DocketPDF/17/17-1229/66274/20181009162145270_Helsinn%20v.%20Teva%20--%20FINAL%20BRIEF.PDF","side":"res","n":45},{"k":"reply","label":"Reply of petitioner Helsinn Healthcare S.A.","date":"2018-11-08","url":"https://www.supremecourt.gov/DocketPDF/17/17-1229/71385/20181108095821758_Helsinn%20reply%20brief%20for%20petitioner%20FINAL.pdf","side":"pet","n":31}],"opinion":"https://www.supremecourt.gov/opinions/18pdf/17-1229_2co3.pdf","tr":true,"items":[{"t":"case","label":"A.B. Chance Co. v. RTE Corp.","cite":"854 F.2d 1307","y":1988,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.2d/854/1307/","by":{"0":"44"},"q":[{"src":"brief","b":0,"text":"[an] offer to sell is enough to bar patentability whether or not the offer is accepted,","cite":"854 F.2d 1307, 1311"}]},{"t":"case","label":"August Technology Corp. v. Camtek, Ltd.","cite":"655 F.3d 1278","y":2011,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/655/1278/","by":{"0":"40"}},{"t":"case","label":"Barnhart v. Thomas","cite":"540 U.S. 20","y":2003,"id":"2003/02-763","sc":1,"by":{"0":"38","2":"32","3":"7"},"q":[{"src":"brief","b":0,"text":"a limiting clause or phrase * * * should ordinarily be read as modifying only the noun or phrase that it immediately follows.","cite":"540 U.S. 20, 26"},{"src":"brief","b":2,"text":"I’d like to go see the first-place Astros, the first-place Dodgers, the first-place Red Sox, the Orioles, or any other first-place team.","cite":"540 U.S. 20"},{"src":"argument","who":"Mr. Jay","text":"I think the best examples that we can give are \"the party or other activity that damages the house\" in Barnhart. \"Party\" -- \"party,\" of course, is not even a term of art."}]},{"t":"case","label":"Beachcombers v. WildeWood Creative Products, Inc.","cite":"31 F.3d 1154","y":1994,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/31/1154/","by":{"0":"43"},"q":[{"src":"argument","who":"Mr. Shanmugam","text":"And, indeed, the legislative history identifies by name some of the public use cases that had so held, cases like the Beachcombers decision from the Federal Circuit and the JumpSport decision."}]},{"t":"case","label":"Bonito Boats, Inc. v. Thunder Craft Boats, Inc.","cite":"489 U.S. 141","y":1989,"id":"1988/87-1346","sc":1,"by":{"0":"5, 6, 46, 47","1":"2, 21, 22, 23","2":"7, 47","3":"10"},"q":[{"src":"brief","b":0,"text":"readily discern[able] from publicly available material.","cite":"489 U.S. 141, 150"},{"src":"brief","b":1,"text":"From their inception, the federal patent laws have embodied a careful balance between the need to promote innovation and the recognition that imitation and refinement through imitation are both necessary to invention itself and the very lifeblood of a competitive economy.","cite":"489 U.S. 141, 146"},{"src":"brief","b":1,"text":"From the Patent Act of 1790[, ch.7, 1 Stat. 109,] to the present day, the public sale of an unpatented article has acted as a complete bar to federal protection of the idea embodied in the article thus placed in public commerce.","cite":"489 U.S. at 148"},{"src":"argument","who":"Justice Breyer","text":"What about Bonito Boats? I mean, in Bonito Boats, this Court, while it isn't necessary for the holding, does quote Learned Hand, and it does say it is a condition upon the inventor's right to a patent that he shall not exploit his discovery competitively after it is ready for patenting."}]},{"t":"case","label":"Brenner v. Manson","cite":"383 U.S. 519","y":1966,"id":"1965/58","sc":1,"by":{"0":"46"}},{"t":"case","label":"Church of the Holy Trinity v. United States","cite":"143 U.S. 457","y":1892,"id":"scdb/1891-129","sc":1,"by":{"0":"29"}},{"t":"case","label":"CSX Transportation, Inc. v. Alabama Department of Revenue","cite":"562 U.S. 277","y":2011,"id":"2010/09-520","sc":1,"by":{"0":"18, 36"},"q":[{"src":"brief","b":0,"text":"avoid the necessity of listing each matter * * * falling within","cite":"562 U.S. 277, 292"}]},{"t":"case","label":"Dart Industries, Inc. v. E.I. du Pont de Nemours & Co.","cite":"489 F.2d 1359","y":1973,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/489/1359/","by":{"0":"44"}},{"t":"case","label":"Federal Maritime Board v. Isbrandtsen Co.","cite":"356 U.S. 481","y":1958,"id":"1957/73","sc":1,"by":{"0":"19, 36","3":"6"},"q":[{"src":"brief","b":0,"text":"other devices not specifically enumerated but similar in purpose and effect","cite":"356 U.S. 481, 492"}]},{"t":"case","label":"Federal Maritime Commission v. Seatrain Lines, Inc.","cite":"411 U.S. 726","y":1973,"id":"1972/71-1647","sc":1,"by":{"0":"passim","2":"34, 35","3":"3, 6, 7"},"q":[{"src":"brief","b":0,"text":"must be read in light of the final, comprehensive category.","cite":"411 U.S. 726, 734"},{"src":"brief","b":0,"text":"was intended to cover onetime, discrete transactions.","cite":"411 U.S. at 736, 745"},{"src":"brief","b":3,"text":"must be read in light of the final, comprehensive category.","cite":"411 U.S. 726, 734"},{"src":"brief","b":3,"text":"limit[s] * * * the specifically enumerated categories as well,","cite":"411 U.S. at 734"}]},{"t":"case","label":"Federal Trade Commission v. Actavis","cite":"570 U.S. 136","y":2013,"id":"2012/12-416","sc":1,"by":{"0":"42"},"q":[{"src":"brief","b":0,"text":"throw[ing] the baby out with the bath water,","cite":"570 U.S. 136, 157"}]},{"t":"case","label":"Graham v. John Deere Co.","cite":"383 U.S. 1","y":1966,"id":"1965/11","sc":1,"by":{"0":"47"},"q":[{"src":"brief","b":0,"text":"remove existent knowledge from the public domain.","cite":"383 U.S. 1, 6"}]},{"t":"case","label":"Griffin v. Oceanic Contractors, Inc.","cite":"458 U.S. 564","y":1982,"id":"1981/81-614","sc":1,"by":{"0":"25"},"q":[{"src":"brief","b":0,"text":"the legislative history * * * confirms that Congress intended the statute to mean exactly what its plain language says.","cite":"458 U.S. 564, 574"}]},{"t":"case","label":"Gustafson v. Alloyd Co.","cite":"513 U.S. 561","y":1995,"id":"1994/93-404","sc":1,"by":{"0":"20, 21, 23, 24","1":"18","3":"3, 5"},"q":[{"src":"brief","b":0,"text":"known by the company [they] keep[].","cite":"513 U.S. 561, 575"},{"src":"brief","b":3,"text":"known by the company [they] keep[].","cite":"513 U.S. 561, 575"}]},{"t":"case","label":"Henson v. Santander Consumer USA Inc.","cite":"137 S. Ct. 1718","y":2017,"id":"2016/16-349","sc":1,"by":{"0":"18"}},{"t":"case","label":"Hibbs v. Winn","cite":"542 U.S. 88","y":2004,"id":"2003/02-1809","sc":1,"by":{"0":"37"}},{"t":"case","label":"Holder v. Martinez Gutierrez","cite":"566 U.S. 583","y":2012,"id":"2011/10-1542","sc":1,"by":{"0":"39","3":"9"},"q":[{"src":"brief","b":0,"text":"the doctrine of congressional ratification applies only when Congress reenacts a statute without relevant change.","cite":"566 U.S. 583, 593"}]},{"t":"case","label":"Kappos v. Hyatt","cite":"566 U.S. 431","y":2012,"id":"2011/10-1219","sc":1,"by":{"0":"5"}},{"t":"case","label":"Kewanee Oil Co. v. Bicron Corp.","cite":"416 U.S. 470","y":1974,"id":"1973/73-187","sc":1,"by":{"0":"48"},"q":[{"src":"brief","b":0,"text":"incentive to inventors to risk the often enormous costs in terms of time, research, and development.","cite":"416 U.S. 470, 480-481"}]},{"t":"case","label":"Limelight Networks, Inc. v. Akamai Technologies, Inc.","cite":"134 S. Ct. 2111","y":2014,"id":"2013/12-786","sc":1,"by":{"0":"4"}},{"t":"case","label":"Lorillard v. Pons","cite":"434 U.S. 575","y":1978,"id":"1977/76-1346","sc":1,"by":{"0":"39"},"q":[{"src":"brief","b":0,"text":"adopt that interpretation when it re-enacts a statute.","cite":"434 U.S. 575, 580"}]},{"t":"case","label":"Medicines Co. v. Hospira, Inc.","cite":"827 F.3d 1363","y":2016,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/827/1363/","by":{"0":"40, 41","2":"9, 48, 54"},"q":[{"src":"brief","b":2,"text":"‘well established … that a single sale or offer to sell is enough to bar patentability’ even if kept secret from the trade.","cite":"827 F.3d 1363, 1376"}]},{"t":"case","label":"Minnesota Mining & Manufacturing Co. v. Chemque, Inc.","cite":"303 F.3d 1294","y":2002,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/303/1294/","by":{"0":"44"},"q":[{"src":"brief","b":0,"text":"actual use by someone at some point,","cite":"303 F.3d 1294, 1307"}]},{"t":"case","label":"New Railhead Manufacturing, L.L.C. v. Vermeer Manufacturing Co.","cite":"298 F.3d 1290","y":2002,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/298/1290/","by":{"0":"43"}},{"t":"case","label":"OddzOn Products, Inc. v. Just Toys, Inc.","cite":"122 F.3d 1396","y":1997,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/122/1396/","by":{"0":"32"}},{"t":"case","label":"Paroline v. United States","cite":"134 S. Ct. 1710","y":2014,"id":"2013/12-8561","sc":1,"by":{"0":"passim","1":"19, 20","3":"3, 6, 7"},"q":[{"src":"argument","who":"Mr. Shanmugam","text":"And so Congress, in including the catch-all provision, did what Congress did in cases like Seatrain Lines and Paroline. It shed light on the meaning of the pre-existing specified provisions, and to be sure, in those cases, everything was enacted at the same time, but, as a textual matter, you have to read the statute as a whole."},{"src":"argument","who":"Justice Kavanaugh","text":"Well, they cite the Paroline case as an example of a case where a term -- a statute was structured like this, and the term in the catch-all then was used to influence the interpretation of the preceding terms."},{"src":"argument","who":"Mr. Jay","text":"One, the Court said in Paroline: Number one, that it might well have reached the same conclusion even if that language didn't appear in the statute because of the strong statute presumption that remedial statutes contain a proximate cause element."}]},{"t":"case","label":"Pfaff v. Wells Electronics, Inc.","cite":"525 U.S. 55","y":1998,"id":"1998/97-1130","sc":1,"by":{"0":"5, 40, 47","1":"3, 22, 24, 28, 29","2":"passim","3":"8, 10, 16"},"q":[{"src":"brief","b":0,"text":"reluctance to allow an inventor to remove existing knowledge from public use.","cite":"525 U.S. 55, 64"},{"src":"brief","b":2,"text":"shall not exploit his discovery competitively after it is ready for patenting.","cite":"525 U.S. at 68"},{"src":"brief","b":2,"text":"the subject of a commercial offer for sale","cite":"525 U.S. at 67"},{"src":"brief","b":3,"text":"[a] similar reluctance * * * to remove existing knowledge from public use.","cite":"525 U.S. 55, 64"},{"src":"argument","who":"Mr. Shanmugam","text":"And all the way through to this Court's decision in Pfaff, this Court has referred to \"the reluctance to allow an inventor to remove existing knowledge from public use\" and has said that that purpose undergirds the on-sale bar."},{"src":"argument","who":"Mr. Stewart","text":"The only exception to that is Pfaff, because Pfaff involved an offer for sale that had not yet been consummated, and the Court held that the bar was triggered even though the invention had not yet been supplied."},{"src":"argument","who":"Justice Kagan","text":"How about if I say it was settled because this Court had decided Pfaff and because the Federal Circuit had a number of cases?"}]},{"t":"case","label":"Puerto Rico v. Franklin California Tax-Free Trust","cite":"136 S. Ct. 1938","y":2016,"id":"2015/15-233","sc":1,"by":{"0":"18, 25"},"q":[{"src":"brief","b":0,"text":"that is also where the inquiry should end.","cite":"136 S. Ct. 1938, 1946"},{"src":"brief","b":0,"text":"that is * * * where the inquiry should end.","cite":"136 S. Ct. at 1946"}]},{"t":"case","label":"Special Devices, Inc. v. OEA, Inc.","cite":"270 F.3d 1353","y":2001,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/270/1353/","by":{"0":"5, 41"},"q":[{"src":"argument","who":"Mr. Shanmugam","text":"We also point to some of the on-sale cases that had extended to sales that did not involve public availability, cases like Special Devices and Caveney."}]},{"t":"case","label":"United States v. Hayes","cite":"555 U.S. 415","y":2009,"id":"2008/07-608","sc":1,"by":{"0":"39"}},{"t":"case","label":"United States v. Standard Brewery","cite":"251 U.S. 210","y":1920,"id":"scdb/1919-173","sc":1,"by":{"0":"19, 37","3":"3"},"q":[{"src":"brief","b":0,"text":"relat[e] to and defin[e] the immediately preceding","cite":"251 U.S. at 218"},{"src":"argument","who":"Mr. Shanmugam","text":"But let me, at the risk of introducing another one, point to this Court's decision in one of my favorite statutory interpretation cases, United States versus Standard Brewery."},{"src":"argument","who":"Mr. Shanmugam","text":"Just as in Standard Brewery, right? That catch-all provision was presumably included for a reason, to include other malt or Venice beverages."}]},{"t":"case","label":"United States v. United Verde Copper Co.","cite":"196 U.S. 207","y":1905,"id":"scdb/1904-162","sc":1,"by":{"0":"19, 37"}},{"t":"law","label":"Pub. L. No. 98-417","url":"https://www.govinfo.gov/link/statute/98/1585","by":{"0":"11"}},{"t":"law","label":"Leahy-Smith America Invents Act, Pub. L. No. 112-29","url":"https://www.govinfo.gov/link/plaw/112/public/29","by":{"0":"passim","1":"2","3":"passim"}},{"t":"law","label":"Pub. L. No. 82-593","url":"https://www.govinfo.gov/link/statute/66/792","by":{"0":"5"}},{"t":"usc","label":"18 U.S.C. § 2259","url":"https://www.law.cornell.edu/uscode/text/18/2259","subs":["(b)(3)(F)","(b)(3)"],"stext":{"head":"§2259. Mandatory restitution","paras":[[0,"(a) In General.—Notwithstanding section 3663 or 3663A, and in addition to any other civil or criminal penalty authorized by law, the court shall order restitution for any offense under this chapter."],[0,"(b) Scope and Nature of Order.—"],[1,"(1) Directions.—Except as provided in paragraph (2), the order of restitution under this section shall direct the defendant to pay the victim (through the appropriate court mechanism) the full amount of the victim's losses."],[1,"(2) Restitution for trafficking in child pornography.—If the defendant was convicted of trafficking in child pornography, the court shall order restitution under this section in an amount to be determined by the court as follows:"],[2,"(A) Determining the full amount of a victim's losses.—The court shall determine the full amount of the victim's losses that were incurred or are reasonably projected to be incurred by the victim as a result of the trafficking in child pornography depicting the victim."],[2,"(B) Determining a restitution amount.—After completing the determination required under subparagraph (A), the court shall order restitution in an amount that reflects the defendant's relative role in the causal process that underlies the victim's losses, but which is no less than $3,000."],[2,"(C) Termination of payment.—A victim's total aggregate recovery pursuant to this section shall not exceed the full amount of the victim's demonstrated losses. After the victim has received restitution in the full amount of the victim's losses as measured by the greatest amount of such losses found in any case involving that victim that has resulted in a final restitution order under this section, the liability of each defendant who is or has been ordered to pay restitution for such losses to that victim shall be terminated. The court may require the victim to provide information concerning the amount of restitution the victim has been paid in other cases for the same losses."],[1,"(3) Enforcement.—An order of restitution under this section shall be issued and enforced in accordance with section 3664 in the same manner as an order under section 3663A."],[1,"(4) Order mandatory.—(A) The issuance of a restitution order under this section is mandatory."],[1,"(B) A court may not decline to issue an order under this section because of—"],[2,"(i) the economic circumstances of the defendant; or"],[2,"(ii) the fact that a victim has, or is entitled to, receive compensation for his or her injuries from the proceeds of insurance or any other source."],[0,"(c) Definitions.—"],[1,"(1) Child pornography production.—For purposes of this section and section 2259A, the term \"child pornography production\" means conduct proscribed by subsections (a) through (c) of section 2251, section 2251A, section 2252A(g) (in cases in which the series of felony violations involves at least 1 of the violations listed in this subsection), section 2260(a), or any offense under chapter 109A or chapter 117 that involved the production of child pornography (as such term is defined in section 2256)."],[1,"(2) Full amount of the victim's losses.—For purposes of this subsection, the term \"full amount of the victim's losses\" includes any costs incurred, or that are reasonably projected to be incurred in the future, by the victim, as a proximate result of the offenses involving the victim, and in the case of trafficking in child pornography offenses, as a proximate result of all trafficking in child pornography offenses involving the same victim, including—"],[2,"(A) medical services relating to physical, psychiatric, or psychological care;"],[2,"(B) physical and occupational therapy or rehabilitation;"],[2,"(C) necessary transportation, temporary housing, and child care expenses;"],[2,"(D) lost income;"],[2,"(E) reasonable attorneys' fees, as well as other costs incurred; and"],[2,"(F) any other relevant losses incurred by the victim."],[1,"(3) Trafficking in child pornography.—For purposes of this section and section 2259A, the term \"trafficking in child pornography\" means conduct proscribed by section 2251(d), 2252, 2252A(a)(1) through (5), 2252A(g) (in cases in which the series of felony violations exclusively involves violations of section 2251(d), 2252, 2252A(a)(1) through (5), or 2260(b)), or 2260(b)."],[1,"(4) Victim.—For purposes of this section, the term \"victim\" means the individual harmed as a result of a commission of a crime under this chapter. In the case of a victim who is under 18 years of age, incompetent, incapacitated, or deceased, the legal guardian of the victim or representative of the victim's estate, another family member, or any other person appointed as suitable by the court, may assume the crime victim's rights under this section, but in no event shall the defendant be named as such representative or guardian."],[0,"(d) Defined Monetary Assistance.—"],[1,"(1) Defined monetary assistance made available at victim's election.—"],[2,"(A) Election to receive defined monetary assistance.—Subject to paragraphs (2) and (3), when a defendant is convicted of trafficking in child pornography, any victim of that trafficking in child pornography may choose to receive defined monetary assistance from the Child Pornography Victims Reserve established under section 1402(d)(6) of the Victims of Crime Act of 1984 (34 U.S.C. 20101(d))."],[2,"(B) Finding.—To be eligible for defined monetary assistance under this subsection, a court shall determine whether the claimant is a victim of the defendant who was convicted of trafficking in child pornography."],[2,"(C) Order.—If a court determines that a claimant is a victim of trafficking in child pornography under subparagraph (B) and the claimant chooses to receive defined monetary assistance, the court shall order payment in accordance with subparagraph (D) to the victim from the Child Pornography Victims Reserve established under section 1402(d)(6) of the Victims of Crime Act of 1984."],[2,"(D) Amount of defined monetary assistance.—The amount of defined monetary assistance payable under this subparagraph shall be equal to—"],[3,"(i) for the first calendar year after the date of enactment of this subsection, $35,000; and"],[3,"(ii) for each calendar year after the year described in clause (i), $35,000 multiplied by the ratio (not less than one) of—"],[4,"(I) the Consumer Price Index for all Urban Consumers (CPI–U, as published by the Bureau of Labor Statistics of the Department of Labor) for the calendar year preceding such calendar year; to"],[4,"(II) the CPI–U for the calendar year 2 years before the calendar year described in clause (i)."],[1,"(2) Limitations on defined monetary assistance.—"],[2,"(A) In general.—A victim may only obtain defined monetary assistance under this subsection once."],[2,"(B) Effect on recovery of other restitution.—A victim who obtains defined monetary assistance under this subsection shall not be barred or limited from receiving restitution against any defendant for any offenses not covered by this section."],[2,"(C) Deduction.—If a victim who received defined monetary assistance under this subsection subsequently seeks restitution under this section, the court shall deduct the amount the victim received in defined monetary assistance when determining the full amount of the victim's losses."],[1,"(3) Limitations on eligibility.—A victim who has collected payment of restitution pursuant to this section in an amount greater than the amount provided for under paragraph (1)(D) shall be ineligible to receive defined monetary assistance under this subsection."],[1,"(4) Attorney fees.—"],[2,"(A) In general.—An attorney representing a victim seeking defined monetary assistance under this subsection may not charge, receive, or collect, and the court may not approve, any payment of fees and costs that in the aggregate exceeds 15 percent of any payment made under this subsection."],[2,"(B) Penalty.—An attorney who violates subparagraph (A) shall be fined under this title, imprisoned not more than 1 year, or both."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/2259?type=usc&year=mostrecent&link-type=html"},"by":{"0":"22","1":"19"},"q":[{"src":"brief","b":0,"text":"final catchall category for ‘any other losses suffered by the victim as a proximate result of the offense.’","cite":"18 U.S.C. 2259(b)(3)(F)"}]},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"1"}},{"t":"usc","label":"35 U.S.C. § 100","url":"https://www.law.cornell.edu/uscode/text/35/100","subs":["(j)"],"stext":{"head":"§100. Definitions","paras":[[0,"When used in this title unless the context otherwise indicates—"],[0,"(a) The term \"invention\" means invention or discovery."],[0,"(b) The term \"process\" means process, art or method, and includes a new use of a known process, machine, manufacture, composition of matter, or material."],[0,"(c) The terms \"United States\" and \"this country\" mean the United States of America, its territories and possessions."],[0,"(d) The word \"patentee\" includes not only the patentee to whom the patent was issued but also the successors in title to the patentee."],[0,"(e) The term \"third-party requester\" means a person requesting ex parte reexamination under section 302 who is not the patent owner."],[0,"(f) The term \"inventor\" means the individual or, if a joint invention, the individuals collectively who invented or discovered the subject matter of the invention."],[0,"(g) The terms \"joint inventor\" and \"coinventor\" mean any 1 of the individuals who invented or discovered the subject matter of a joint invention."],[0,"(h) The term \"joint research agreement\" means a written contract, grant, or cooperative agreement entered into by 2 or more persons or entities for the performance of experimental, developmental, or research work in the field of the claimed invention."],[0,"(i)(1) The term \"effective filing date\" for a claimed invention in a patent or application for patent means—"],[1,"(A) if subparagraph (B) does not apply, the actual filing date of the patent or the application for the patent containing a claim to the invention; or"],[1,"(B) the filing date of the earliest application for which the patent or application is entitled, as to such invention, to a right of priority under section 119, 365(a), 365(b), 386(a), or 386(b) or to the benefit of an earlier filing date under section 120, 121, 365(c), or 386(c)."],[0,"(2) The effective filing date for a claimed invention in an application for reissue or reissued patent shall be determined by deeming the claim to the invention to have been contained in the patent for which reissue was sought."],[0,"(j) The term \"claimed invention\" means the subject matter defined by a claim in a patent or an application for a patent."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/35/100?type=usc&year=mostrecent&link-type=html"},"by":{"0":"7, 25, 40","3":"9"},"q":[{"src":"brief","b":0,"text":"the subject matter defined by a claim in a patent or an application for a patent.","cite":"35 U.S.C. 100(j)"}]},{"t":"usc","label":"35 U.S.C. § 102","url":"https://www.law.cornell.edu/uscode/text/35/102","subs":["(a)(2006)","(a)(1)","(b)(2006)","(b)(1)","(b)(1)(A)","(b)(1)(B)","(g)(2006)","(a)(1952)","(b)(1952)","(b)(1994)","(b)","(a)"],"stext":{"head":"§102. Conditions for patentability; novelty","paras":[[0,"(a) Novelty; Prior Art.—A person shall be entitled to a patent unless—"],[1,"(1) the claimed invention was patented, described in a printed publication, or in public use, on sale, or otherwise available to the public before the effective filing date of the claimed invention; or"],[1,"(2) the claimed invention was described in a patent issued under section 151, or in an application for patent published or deemed published under section 122(b), in which the patent or application, as the case may be, names another inventor and was effectively filed before the effective filing date of the claimed invention."],[0,"(b) Exceptions.—"],[1,"(1) Disclosures made 1 year or less before the effective filing date of the claimed invention.—A disclosure made 1 year or less before the effective filing date of a claimed invention shall not be prior art to the claimed invention under subsection (a)(1) if—"],[2,"(A) the disclosure was made by the inventor or joint inventor or by another who obtained the subject matter disclosed directly or indirectly from the inventor or a joint inventor; or"],[2,"(B) the subject matter disclosed had, before such disclosure, been publicly disclosed by the inventor or a joint inventor or another who obtained the subject matter disclosed directly or indirectly from the inventor or a joint inventor."],[1,"(2) Disclosures appearing in applications and patents.—A disclosure shall not be prior art to a claimed invention under subsection (a)(2) if—"],[2,"(A) the subject matter disclosed was obtained directly or indirectly from the inventor or a joint inventor;"],[2,"(B) the subject matter disclosed had, before such subject matter was effectively filed under subsection (a)(2), been publicly disclosed by the inventor or a joint inventor or another who obtained the subject matter disclosed directly or indirectly from the inventor or a joint inventor; or"],[2,"(C) the subject matter disclosed and the claimed invention, not later than the effective filing date of the claimed invention, were owned by the same person or subject to an obligation of assignment to the same person."],[0,"(c) Common Ownership Under Joint Research Agreements.—Subject matter disclosed and a claimed invention shall be deemed to have been owned by the same person or subject to an obligation of assignment to the same person in applying the provisions of subsection (b)(2)(C) if—"],[1,"(1) the subject matter disclosed was developed and the claimed invention was made by, or on behalf of, 1 or more parties to a joint research agreement that was in effect on or before the effective filing date of the claimed invention;"],[1,"(2) the claimed invention was made as a result of activities undertaken within the scope of the joint research agreement; and"],[1,"(3) the application for patent for the claimed invention discloses or is amended to disclose the names of the parties to the joint research agreement."],[0,"(d) Patents and Published Applications Effective as Prior Art.—For purposes of determining whether a patent or application for patent is prior art to a claimed invention under subsection (a)(2), such patent or application shall be considered to have been effectively filed, with respect to any subject matter described in the patent or application—"],[1,"(1) if paragraph (2) does not apply, as of the actual filing date of the patent or the application for patent; or"],[1,"(2) if the patent or application for patent is entitled to claim a right of priority under section 119, 365(a), 365(b), 386(a), or 386(b), or to claim the benefit of an earlier filing date under section 120, 121, 365(c), or 386(c), based upon 1 or more prior filed applications for patent, as of the filing date of the earliest such application that describes the subject matter."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/35/102?type=usc&year=mostrecent&link-type=html"},"by":{"0":"2, 46, 31, passim, 3, 5, 34, 44, 45, 45, 32","1":"2, 14, 20, 23, passim, 4, 23, 29, 2, 4, 14, 15, 2","2":"passim, 20, 37, 38, 50, 17, 37, 38, 38, 38","3":"passim, 12, 12, 13"},"q":[{"src":"brief","b":0,"text":"invention was * * * in public use or on sale in this country, more than one year prior to the date of the application for patent in the United States.","cite":"35 U.S.C. 102(b)"},{"src":"brief","b":0,"text":"the claimed invention was * * * in public use, on sale, or otherwise available to the public before the effective filing date of the claimed invention.","cite":"35 U.S.C. 102(a)(1)"},{"src":"brief","b":1,"text":"[a] person shall be entitled to a patent unless * * * the claimed invention was patented, described in a printed publication, or in public use, on sale, or otherwise available to the public before the effective filing date of the claimed invention.","cite":"35 U.S.C. 102(a)(1)"},{"src":"brief","b":1,"text":"[a] disclosure made 1 year or less before the effective filing date of a claimed invention shall not be prior art to the claimed invention under subsection (a)(1).","cite":"35 U.S.C. 102(b)(1)"},{"src":"brief","b":3,"text":"patented, described in a printed publication, or in public use, on sale, or otherwise available to the public before the effective filing date","cite":"35 U.S.C. 102(a)(1)"},{"src":"brief","b":3,"text":"the subject matter disclosed had * * * [earlier] been publicly disclosed by the inventor.","cite":"35 U.S.C. 102(b)(1)(B)"}]},{"t":"usc","label":"35 U.S.C. § 103","url":"https://www.law.cornell.edu/uscode/text/35/103","by":{"0":"46"}},{"t":"usc","label":"35 U.S.C. § 321","url":"https://www.law.cornell.edu/uscode/text/35/321","subs":["(c)"],"stext":{"head":"§321. Post-grant review","paras":[[0,"(a) In General.—Subject to the provisions of this chapter, a person who is not the owner of a patent may file with the Office a petition to institute a post-grant review of the patent. The Director shall establish, by regulation, fees to be paid by the person requesting the review, in such amounts as the Director determines to be reasonable, considering the aggregate costs of the post-grant review."],[0,"(b) Scope.—A petitioner in a post-grant review may request to cancel as unpatentable 1 or more claims of a patent on any ground that could be raised under paragraph (2) or (3) of section 282(b) (relating to invalidity of the patent or any claim)."],[0,"(c) Filing Deadline.—A petition for a post-grant review may only be filed not later than the date that is 9 months after the date of the grant of the patent or of the issuance of a reissue patent (as the case may be)."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/35/321?type=usc&year=mostrecent&link-type=html"},"by":{"0":"34, 35","2":"51"}},{"t":"usc","label":"35 U.S.C. § 326","url":"https://www.law.cornell.edu/uscode/text/35/326","subs":["(a)(5)","(a)(6)","(a)(11)"],"stext":{"head":"§326. Conduct of post-grant review","paras":[[0,"(a) Regulations.—The Director shall prescribe regulations—"],[1,"(1) providing that the file of any proceeding under this chapter shall be made available to the public, except that any petition or document filed with the intent that it be sealed shall, if accompanied by a motion to seal, be treated as sealed pending the outcome of the ruling on the motion;"],[1,"(2) setting forth the standards for the showing of sufficient grounds to institute a review under subsections (a) and (b) of section 324;"],[1,"(3) establishing procedures for the submission of supplemental information after the petition is filed;"],[1,"(4) establishing and governing a post-grant review under this chapter and the relationship of such review to other proceedings under this title;"],[1,"(5) setting forth standards and procedures for discovery of relevant evidence, including that such discovery shall be limited to evidence directly related to factual assertions advanced by either party in the proceeding;"],[1,"(6) prescribing sanctions for abuse of discovery, abuse of process, or any other improper use of the proceeding, such as to harass or to cause unnecessary delay or an unnecessary increase in the cost of the proceeding;"],[1,"(7) providing for protective orders governing the exchange and submission of confidential information;"],[1,"(8) providing for the filing by the patent owner of a response to the petition under section 323 after a post-grant review has been instituted, and requiring that the patent owner file with such response, through affidavits or declarations, any additional factual evidence and expert opinions on which the patent owner relies in support of the response;"],[1,"(9) setting forth standards and procedures for allowing the patent owner to move to amend the patent under subsection (d) to cancel a challenged claim or propose a reasonable number of substitute claims, and ensuring that any information submitted by the patent owner in support of any amendment entered under subsection (d) is made available to the public as part of the prosecution history of the patent;"],[1,"(10) providing either party with the right to an oral hearing as part of the proceeding;"],[1,"(11) requiring that the final determination in any post-grant review be issued not later than 1 year after the date on which the Director notices the institution of a proceeding under this chapter, except that the Director may, for good cause shown, extend the 1-year period by not more than 6 months, and may adjust the time periods in this paragraph in the case of joinder under section 325(c); and"],[1,"(12) providing the petitioner with at least 1 opportunity to file written comments within a time period established by the Director."],[0,"(b) Considerations.—In prescribing regulations under this section, the Director shall consider the effect of any such regulation on the economy, the integrity of the patent system, the efficient administration of the Office, and the ability of the Office to timely complete proceedings instituted under this chapter."],[0,"(c) Patent Trial and Appeal Board.—The Patent Trial and Appeal Board shall, in accordance with section 6, conduct each post-grant review instituted under this chapter."],[0,"(d) Amendment of the Patent.—"],[1,"(1) In general.—During a post-grant review instituted under this chapter, the patent owner may file 1 motion to amend the patent in 1 or more of the following ways:"],[2,"(A) Cancel any challenged patent claim."],[2,"(B) For each challenged claim, propose a reasonable number of substitute claims."],[1,"(2) Additional motions.—Additional motions to amend may be permitted upon the joint request of the petitioner and the patent owner to materially advance the settlement of a proceeding under section 327, or upon the request of the patent owner for good cause shown."],[1,"(3) Scope of claims.—An amendment under this subsection may not enlarge the scope of the claims of the patent or introduce new matter."],[0,"(e) Evidentiary Standards.—In a post-grant review instituted under this chapter, the petitioner shall have the burden of proving a proposition of unpatentability by a preponderance of the evidence."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/35/326?type=usc&year=mostrecent&link-type=html"},"by":{"0":"35, 35, 35","3":"18, 18, 18"}},{"t":"reg","label":"78 Fed. Reg. 11,059","url":"https://www.govinfo.gov/link/fr/78/11059","by":{"0":"8"}},{"t":"case","label":"Atlanta Attachment Co. v. Leggett & Platt, Inc.","cite":"516 F.3d 1361","y":2008,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/516/1361/","by":{"1":"23"},"q":[{"src":"brief","b":1,"text":"[t]he overriding concern of the onsale bar is an inventor’s attempt to commercialize his invention beyond the statutory term.","cite":"516 F.3d 1361, 1365"}]},{"t":"case","label":"Blue Calypso, LLC v. Groupon, Inc.","cite":"815 F.3d 1331","y":2016,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/815/1331/","by":{"1":"2, 16, 17","3":"5"}},{"t":"case","label":"Consolidated Fruit-Jar Co. v. Wright","cite":"94 U.S. 92","y":1877,"id":"scdb/1876-110","sc":1,"by":{"1":"22","2":"2, 25, 52, 54"},"q":[{"src":"argument","who":"Mr. Jay","text":"But I think the history goes much further back that than that, and I would urge the Court to look at a number of the late 19th Century cases, such as Consolidated Fruit-Jar, in which the Court said that the inventor is not allowed to derive any benefit from the sale or the use of his machine unless he begins -- unless he applies for patenting within the then grace period."}]},{"t":"case","label":"Egbert v. Lippmann","cite":"104 U.S. 333","y":1881,"id":"scdb/1881-047","sc":1,"by":{"1":"17"}},{"t":"case","label":"Elizabeth v. Pavement Co.","cite":"97 U.S. 126","y":1878,"id":"scdb/1877-248","sc":1,"by":{"1":"22","2":"7","3":"16"},"q":[{"src":"brief","b":1,"text":"does not voluntarily allow others to make it and use it, and so long as it is not on sale for general use.","cite":"97 U.S. 126, 135"},{"src":"brief","b":2,"text":"an inventor acquires an undue advantage over the public by delaying to take out a patent, inasmuch as he thereby preserves the monopoly to himself for a longer period than is allowed by the policy of the law.","cite":"97 U.S. 126, 137"}]},{"t":"case","label":"Kellogg Co. v. National Biscuit Co.","cite":"305 U.S. 111","y":1938,"id":"scdb/1938-009","sc":1,"by":{"1":"27"}},{"t":"case","label":"Life Techs. Corp. v. Promega Corp.","cite":"137 S. Ct. 734","y":2017,"id":"2016/14-1538","sc":1,"by":{"1":"17"},"q":[{"src":"brief","b":1,"text":"[a] word is given more precise content by the neighboring words with which it is associated.","cite":"137 S. Ct. 734, 740"}]},{"t":"case","label":"Madstad Eng’g, Inc. v. United States Patent & Trademark Office","cite":"756 F.3d 1366","y":2014,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/756/1366/","by":{"1":"24"}},{"t":"case","label":"Markman v. Westview Instruments, Inc.","cite":"517 U.S. 370","y":1996,"id":"1995/95-26","sc":1,"by":{"1":"16"}},{"t":"case","label":"Netscape Commc’ns Corp. v. Konrad","cite":"295 F.3d 1315","y":2002,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/295/1315/","by":{"1":"23"}},{"t":"case","label":"STX, LLC v. Brine, Inc.","cite":"211 F.3d 588","y":2000,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/211/588/","by":{"1":"23"}},{"t":"case","label":"Scott Paper Co. v. Marcalus Mfg. Co.","cite":"326 U.S. 249","y":1945,"id":"scdb/1945-011","sc":1,"by":{"1":"27"}},{"t":"case","label":"United States v. Fausto","cite":"484 U.S. 439","y":1988,"id":"1987/86-595","sc":1,"by":{"1":"18"}},{"t":"case","label":"United States v. Williams","cite":"553 U.S. 285","y":2008,"id":"2007/06-694","sc":1,"by":{"1":"17","3":"7"},"q":[{"src":"brief","b":3,"text":"susceptible of multiple * * * meanings.","cite":"553 U.S. 285, 294"}]},{"t":"case","label":"Yates v. United States","cite":"135 S. Ct. 1074","y":2015,"id":"2014/13-7451","sc":1,"by":{"1":"18"},"q":[{"src":"brief","b":1,"text":"to ‘avoid ascribing to one word a meaning so broad that it is inconsistent with its accompanying words, thus giving unintended breadth to the Acts of Congress.’","cite":"135 S. Ct. 1074, 1085"}]},{"t":"usc","label":"35 U.S.C. § 1","url":"https://www.law.cornell.edu/uscode/text/35/1","by":{"1":"4"}},{"t":"usc","label":"35 U.S.C. § 2","url":"https://www.law.cornell.edu/uscode/text/35/2","subs":["(a)(1)"],"by":{"1":"1"}},{"t":"usc","label":"35 U.S.C. § 112","url":"https://www.law.cornell.edu/uscode/text/35/112","subs":["(a)","(b)"],"stext":{"head":"§112. Specification","paras":[[0,"(a) In General.—The specification shall contain a written description of the invention, and of the manner and process of making and using it, in such full, clear, concise, and exact terms as to enable any person skilled in the art to which it pertains, or with which it is most nearly connected, to make and use the same, and shall set forth the best mode contemplated by the inventor or joint inventor of carrying out the invention."],[0,"(b) Conclusion.—The specification shall conclude with one or more claims particularly pointing out and distinctly claiming the subject matter which the inventor or a joint inventor regards as the invention."],[0,"(c) Form.—A claim may be written in independent or, if the nature of the case admits, in dependent or multiple dependent form."],[0,"(d) Reference in Dependent Forms.—Subject to subsection (e), a claim in dependent form shall contain a reference to a claim previously set forth and then specify a further limitation of the subject matter claimed. A claim in dependent form shall be construed to incorporate by reference all the limitations of the claim to which it refers."],[0,"(e) Reference in Multiple Dependent Form.—A claim in multiple dependent form shall contain a reference, in the alternative only, to more than one claim previously set forth and then specify a further limitation of the subject matter claimed. A multiple dependent claim shall not serve as a basis for any other multiple dependent claim. A multiple dependent claim shall be construed to incorporate by reference all the limitations of the particular claim in relation to which it is being considered."],[0,"(f) Element in Claim for a Combination.—An element in a claim for a combination may be expressed as a means or step for performing a specified function without the recital of structure, material, or acts in support thereof, and such claim shall be construed to cover the corresponding structure, material, or acts described in the specification and equivalents thereof."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/35/112?type=usc&year=mostrecent&link-type=html"},"by":{"1":"3, 16"},"q":[{"src":"brief","b":1,"text":"to enable any person skilled in the art * * * to make and use the","cite":"35 U.S.C. 112(a)"}]},{"t":"usc","label":"35 U.S.C. § 131","url":"https://www.law.cornell.edu/uscode/text/35/131","by":{"1":"1"}},{"t":"case","label":"Air Wisconsin Airlines Corp. v. Hoeper","cite":"571 U.S. 237","y":2014,"id":"2013/12-315","sc":1,"by":{"2":"27"},"q":[{"src":"brief","b":2,"text":"It is a cardinal rule of statutory construction that, when Congress employs a term of art, it presumably knows and adopts the cluster of ideas that were attached to each borrowed word in the body of learning from which it is taken.","cite":"571 U.S. 237, 248"}]},{"t":"case","label":"Ali v. Fed. Bureau of Prisons","cite":"552 U.S. 214","y":2008,"id":"2007/06-9130","sc":1,"by":{"2":"19, 33"},"q":[{"src":"brief","b":2,"text":"create ambiguity where the statute’s text and structure suggest none.","cite":"552 U.S. 214, 227"},{"src":"brief","b":2,"text":"create ambiguity when the statute’s text and structure suggest none.","cite":"552 U.S. at 227"}]},{"t":"case","label":"Cont’l Plastic Containers v. Owens Brockway Plastic Prods., Inc.","cite":"141 F.3d 1073","y":1998,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/141/1073/","by":{"2":"9"},"q":[{"src":"brief","b":2,"text":"the pri- 2 E.g., Merck & Cie v. Watson Labs., Inc., 822 F.3d 1347, 1351 (Fed. Cir. 2016) (responding to a single customer’s request to purchase product by returning price, delivery, and payment terms triggered the on-sale bar); Scaltech, Inc. v. Retec/Tetra, LLC, 269 F.3d 1321, 1328 (Fed. Cir. 2001) (offer to sell a service mary policy underlying an ‘on-sale’ case is that of prohibiting the commercial exploitation of the design beyond the statutorily prescribed time period.","cite":"141 F.3d 1073, 1079"}]},{"t":"case","label":"D.L. Auld Co. v. Chroma Graphics Corp.","cite":"714 F.2d 1144","y":1983,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.2d/714/1144/","by":{"2":"48"}},{"t":"case","label":"Dep’t of Homeland Sec. v. MacLean","cite":"135 S. Ct. 913","y":2015,"url":"https://www.courtlistener.com/c/S.%20Ct./135/913/","sc":1,"by":{"2":"28, 29, 32"}},{"t":"case","label":"Exxon Mobil Corp. v. Allapattah Servs., Inc.","cite":"545 U.S. 546","y":2005,"id":"2004/04-70","sc":1,"by":{"2":"40"},"q":[{"src":"brief","b":2,"text":"strategic manipulations of legislative history to secure results [Members] were unable to achieve through the statutory text.","cite":"545 U.S. 546, 568"}]},{"t":"case","label":"FDA v. Brown & Williamson Tobacco Corp.","cite":"529 U.S. 120","y":2000,"id":"1999/98-1152","sc":1,"by":{"2":"37"}},{"t":"case","label":"Graham Cty. Soil & Water Conservation Dist. v. United States ex rel. Wilson","cite":"559 U.S. 280","y":2010,"id":"2009/08-304","sc":1,"by":{"2":"19, 34"},"q":[{"src":"brief","b":2,"text":"each quite distinct from the other no matter how construed.","cite":"559 U.S. at 288"},{"src":"brief","b":2,"text":"‘rob’ any one of [the statutory bars] ‘of its independent and ordinary significance.’","cite":"559 U.S. at 288"}]},{"t":"case","label":"Hall v. Macneale","cite":"107 U.S. 90","y":1883,"id":"scdb/1882-127","sc":1,"by":{"2":"25"}},{"t":"case","label":"Kellogg Brown & Root Servs., Inc. v. United States ex rel. Carter","cite":"135 S. Ct. 1970","y":2015,"url":"https://www.courtlistener.com/c/S.%20Ct./135/1970/","sc":1,"by":{"2":"29"},"q":[{"src":"brief","b":2,"text":"[f]undamental changes in the scope of a statute are not typically accomplished with so subtle a move.","cite":"135 S. Ct. 1970, 1977"}]},{"t":"case","label":"Leegin Creative Leather Prods., Inc. v. PSKS, Inc.","cite":"551 U.S. 877","y":2007,"id":"2006/06-480","sc":1,"by":{"2":"55"}},{"t":"case","label":"Lockhart v. United States","cite":"136 S. Ct. 958","y":2016,"id":"2015/14-8358","sc":1,"by":{"2":"30, 36"}},{"t":"case","label":"Loughrin v. United States","cite":"134 S. Ct. 2384","y":2014,"id":"2013/13-316","sc":1,"by":{"2":"36, 38","3":"6"},"q":[{"src":"brief","b":2,"text":"courts must give effect, if possible, to every clause and word of a statute.","cite":"134 S. Ct. 2384, 2390"}]},{"t":"case","label":"Merck & Cie v. Watson Labs., Inc.","cite":"822 F.3d 1347","y":2016,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/822/1347/","by":{"2":"8"}},{"t":"case","label":"Merck KGaA v. Integra Lifesciences I, Ltd.","cite":"545 U.S. 193","y":2005,"id":"2004/03-1237","sc":1,"by":{"2":"58"}},{"t":"case","label":"Metallizing Eng’g Co. v. Kenyon Bearing & Auto Parts Co.","cite":"153 F.2d 516","y":1946,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/153/516/","by":{"2":"passim"},"q":[{"src":"brief","b":2,"text":"it is a condition upon an inventor’s right to a patent that he shall not exploit his discovery competitively after it is ready for patenting; he must content himself with either secrecy, or legal monopoly.","cite":"153 F.2d 516, 520"},{"src":"brief","b":2,"text":"a later legal monopoly by means of a patent.","cite":"153 F.2d at 519"},{"src":"argument","who":"Mr. Shanmugam","text":"I don't think we would dispute that that is one way of characterizing the underlying purpose, and that is what Judge Hand said in the Metallizing opinion."},{"src":"argument","who":"Mr. Shanmugam","text":"Now, with regard to this alternative formulation of the purpose, which I think really first appeared prominently in Judge Hand's opinion in Metallizing and then did - did get picked up in a couple of this Court's decisions, I'm willing to accept that, when you have a sale, there is obviously a commercial aspect to that."}]},{"t":"case","label":"Midatlantic Nat’l Bank v. N.J. Dep’t of Envtl. Prot.","cite":"474 U.S. 494","y":1986,"id":"1985/84-801","sc":1,"by":{"2":"27"},"q":[{"src":"brief","b":2,"text":"[t]he normal rule of statutory construction is that if Congress intends for legislation to change the interpretation of a judicially created concept, it makes that intent specific.","cite":"474 U.S. 494"}]},{"t":"case","label":"NLRB v. SW General, Inc.","cite":"137 S. Ct. 929","y":2017,"id":"2016/15-1251","sc":1,"by":{"2":"20, 43"},"q":[{"src":"brief","b":2,"text":"rank among the least illuminating forms of legislative history.","cite":"137 S. Ct. 929, 943"},{"src":"brief","b":2,"text":"[t]his is a good example of why floor statements by individual legislators rank among the least illuminating forms of legislative history.","cite":"137 S. Ct. at 943"}]},{"t":"case","label":"Norfolk S. Ry. Co. v. Sorrell","cite":"549 U.S. 158","y":2007,"id":"2006/05-746","sc":1,"by":{"2":"51"},"q":[{"src":"brief","b":2,"text":"the statute’s … objective[s] must be the law.","cite":"549 U.S. 158, 171"}]},{"t":"case","label":"Pa. Dep’t of Corr. v. Yeskey","cite":"524 U.S. 206","y":1998,"id":"1997/97-634","sc":1,"by":{"2":"52"},"q":[{"src":"brief","b":2,"text":"cannot limit the plain meaning of the text.","cite":"524 U.S. 206, 212"}]},{"t":"case","label":"Plumtree Software, Inc. v. Datamize, LLC","cite":"473 F.3d 1152","y":2006,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/473/1152/","by":{"2":"48"}},{"t":"case","label":"Russell Motor Car Co. v. United States","cite":"261 U.S. 514","y":1923,"id":"scdb/1922-150","sc":1,"by":{"2":"33, 34","3":"8"}},{"t":"case","label":"S.D. Warren Co. v. Me. Bd. of Envtl. Prot.","cite":"547 U.S. 370","y":2006,"id":"2005/04-1527","sc":1,"by":{"2":"33"}},{"t":"case","label":"Scaltech, Inc. v. Retec/Tetra, LLC","cite":"269 F.3d 1321","y":2001,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/269/1321/","by":{"2":"8, 48"}},{"t":"case","label":"Smith & Griggs Mfg. Co. v. Sprague","cite":"123 U.S. 249","y":1887,"id":"scdb/1887-028","sc":1,"by":{"2":"25"}},{"t":"case","label":"TC Heartland LLC v. Kraft Foods Group Brands LLC","cite":"137 S. Ct. 1514","y":2017,"id":"2016/16-341","sc":1,"by":{"2":"27, 28","3":"11"},"q":[{"src":"brief","b":2,"text":"it ordinarily provides a relatively clear indication of its intent in the text of the amended provision.","cite":"137 S. Ct. 1514, 1520"},{"src":"brief","b":3,"text":"relatively clear indication of its intent in the text of the amended provision.","cite":"137 S. Ct. 1514, 1520"}]},{"t":"case","label":"United States v. Reorganized CF&I Fabricators of Utah, Inc.","cite":"518 U.S. 213","y":1996,"id":"1995/95-325","sc":1,"by":{"2":"27"}},{"t":"case","label":"United States v. Stevens","cite":"559 U.S. 460","y":2010,"id":"2009/08-769","sc":1,"by":{"2":"33"}},{"t":"usc","label":"21 U.S.C. § 355","url":"https://www.law.cornell.edu/uscode/text/21/355","subs":["(j)(2)(A)(vii)(IV)"],"by":{"2":"14"}},{"t":"usc","label":"35 U.S.C. § 271","url":"https://www.law.cornell.edu/uscode/text/35/271","subs":["(e)(1)","(e)(2)(A)"],"by":{"2":"58, 14"}},{"t":"usc","label":"35 U.S.C. § 322","url":"https://www.law.cornell.edu/uscode/text/35/322","subs":["(a)(3)"],"by":{"2":"51"}},{"t":"case","label":"Arthur Andersen LLP v. United States","cite":"544 U.S. 696","y":2005,"id":"2004/04-368","sc":1,"by":{"3":"3, 4, 8"},"q":[{"src":"brief","b":3,"text":"simply [to] interpret the statute as written.","cite":"544 U.S. 696, 705"}]},{"t":"case","label":"Conroy v. Aniskoff","cite":"507 U.S. 511","y":1993,"id":"1992/91-1353","sc":1,"by":{"3":"13"},"q":[{"src":"brief","b":3,"text":"entering a crowded cocktail party and looking over the heads of the guests for one’s friends.","cite":"507 U.S. 511, 519"}]},{"t":"case","label":"Garcia v. United States","cite":"469 U.S. 70","y":1984,"id":"1984/83-6061","sc":1,"by":{"3":"14, 15"},"q":[{"src":"brief","b":3,"text":"the authoritative source for finding the Legislature’s intent.","cite":"469 U.S. 70, 76"}]},{"t":"case","label":"Jama v. Immigration & Customs Enforcement","cite":"543 U.S. 335","y":2005,"id":"2004/03-674","sc":1,"by":{"3":"9, 10"},"q":[{"src":"brief","b":3,"text":"supposed judicial consensus [must be] so broad and unquestioned that [the Court] must presume Congress knew of and endorsed it.","cite":"543 U.S. 335, 349"}]},{"t":"usc","label":"35 U.S.C. § 273","url":"https://www.law.cornell.edu/uscode/text/35/273","subs":["(a)","(a)(3)(1999)","(e)(1)"],"by":{"3":"19, 20, 20, 20"}}]};